export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女はメモを裏返した。", ruby: [{"start":0,"end":2,"reading":"かのじょ"},{"start":6,"end":8,"reading":"うらがえ"}], background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "ペン先が長いこと止まった。看護記録なら何千枚と書いてきたけれど、こんなに考えこんだことは一度もない。意識清明、バイタル安定、主訴なし。", ruby: [{"start":2,"end":3,"reading":"さき"},{"start":4,"end":5,"reading":"なが"},{"start":8,"end":9,"reading":"と"},{"start":13,"end":17,"reading":"かんごきろく"},{"start":19,"end":22,"reading":"なんぜんまい"},{"start":23,"end":24,"reading":"か"},{"start":36,"end":37,"reading":"かんが"},{"start":44,"end":46,"reading":"いちど"},{"start":50,"end":54,"reading":"いしきせいめい"},{"start":59,"end":61,"reading":"あんてい"},{"start":62,"end":64,"reading":"しゅそ"}], background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "結局、こう書いた。「靴下はこちらで預かっています。状態は安定。勇気については、洗濯機は『見ていない』とのこと。経過観察を推奨します。」", ruby: [{"start":0,"end":2,"reading":"けっきょく"},{"start":5,"end":6,"reading":"か"},{"start":10,"end":12,"reading":"くつした"},{"start":17,"end":18,"reading":"あず"},{"start":25,"end":27,"reading":"じょうたい"},{"start":28,"end":30,"reading":"あんてい"},{"start":31,"end":33,"reading":"ゆうき"},{"start":39,"end":42,"reading":"せんたくき"},{"start":44,"end":45,"reading":"み"},{"start":55,"end":59,"reading":"けいかかんさつ"},{"start":60,"end":62,"reading":"すいしょう"}], background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.ZhouYining, character: "以寧", dialogue: "（心の声）……申し送りみたいになった。まあ、いいか。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":7,"end":8,"reading":"もう"},{"start":9,"end":10,"reading":"おく"}], background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.ZhouYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "メモをチャック袋に戻し、灰色の靴下に押しこんで、彼の洗濯物の袋の上に置く。それから四つ目の椅子に戻って、服をたたみはじめた。ものすごく、ゆっくりと。", ruby: [{"start":7,"end":8,"reading":"ぶくろ"},{"start":9,"end":10,"reading":"もど"},{"start":12,"end":14,"reading":"はいいろ"},{"start":15,"end":17,"reading":"くつした"},{"start":18,"end":19,"reading":"お"},{"start":24,"end":25,"reading":"かれ"},{"start":26,"end":29,"reading":"せんたくもの"},{"start":30,"end":31,"reading":"ふくろ"},{"start":32,"end":33,"reading":"うえ"},{"start":34,"end":35,"reading":"お"},{"start":41,"end":42,"reading":"よっ"},{"start":43,"end":44,"reading":"め"},{"start":45,"end":47,"reading":"いす"},{"start":48,"end":49,"reading":"もど"},{"start":52,"end":53,"reading":"ふく"}], background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "五分後、ドアが開いた。", ruby: [{"start":0,"end":3,"reading":"ごふんご"},{"start":7,"end":8,"reading":"あ"}], background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼は雨のにおいをまとって入ってきた。手にはホットの豆乳のボトル。適当につかんできたように見えた。なぜそれを持っているのか、本人もよく分かっていないようだったから。", ruby: [{"start":0,"end":1,"reading":"かれ"},{"start":2,"end":3,"reading":"あめ"},{"start":12,"end":13,"reading":"はい"},{"start":18,"end":19,"reading":"て"},{"start":25,"end":27,"reading":"とうにゅう"},{"start":32,"end":34,"reading":"てきとう"},{"start":44,"end":45,"reading":"み"},{"start":53,"end":54,"reading":"も"},{"start":61,"end":63,"reading":"ほんにん"},{"start":66,"end":67,"reading":"わ"}], background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "靴下に気づいて、彼は動きを止めた。座って、チャック袋を開けて、読む。長いこと読んでいた。外国語で書いてしまったのかと、彼女が不安になるくらいに。", ruby: [{"start":0,"end":2,"reading":"くつした"},{"start":3,"end":4,"reading":"き"},{"start":8,"end":9,"reading":"かれ"},{"start":10,"end":11,"reading":"うご"},{"start":13,"end":14,"reading":"と"},{"start":17,"end":18,"reading":"すわ"},{"start":25,"end":26,"reading":"ぶくろ"},{"start":27,"end":28,"reading":"あ"},{"start":31,"end":32,"reading":"よ"},{"start":34,"end":35,"reading":"なが"},{"start":38,"end":39,"reading":"よ"},{"start":44,"end":47,"reading":"がいこくご"},{"start":48,"end":49,"reading":"か"},{"start":59,"end":61,"reading":"かのじょ"},{"start":62,"end":64,"reading":"ふあん"}], background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "それから赤ペンのキャップを抜いて何か書きつけ、たたみ直すと、靴下を二人のあいだの空いた椅子に置いた。", ruby: [{"start":4,"end":5,"reading":"あか"},{"start":13,"end":14,"reading":"ぬ"},{"start":16,"end":17,"reading":"なに"},{"start":18,"end":19,"reading":"か"},{"start":26,"end":27,"reading":"なお"},{"start":30,"end":32,"reading":"くつした"},{"start":33,"end":35,"reading":"ふたり"},{"start":40,"end":41,"reading":"あ"},{"start":43,"end":45,"reading":"いす"},{"start":46,"end":47,"reading":"お"}], background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "何も言わずに。", ruby: [{"start":0,"end":1,"reading":"なに"},{"start":2,"end":3,"reading":"い"}], background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.ZhouYining, character: "以寧", dialogue: "（心の声）……なるほど。そういうルールね。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"}], background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.ZhouYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "手に取る。「入院を受け入れてくださり、ありがとうございます。家族より質問です。勇気が三号のゴムパッキンに挟まっている可能性はありますか。」", ruby: [{"start":0,"end":1,"reading":"て"},{"start":2,"end":3,"reading":"と"},{"start":6,"end":8,"reading":"にゅういん"},{"start":9,"end":10,"reading":"う"},{"start":11,"end":12,"reading":"い"},{"start":30,"end":32,"reading":"かぞく"},{"start":34,"end":36,"reading":"しつもん"},{"start":39,"end":41,"reading":"ゆうき"},{"start":42,"end":44,"reading":"さんごう"},{"start":52,"end":53,"reading":"はさ"},{"start":58,"end":61,"reading":"かのうせい"}], background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.ZhouYining, character: "以寧", dialogue: "（心の声）私の書式をまねしてる。翻訳者だもの、まねするに決まってる。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":5,"end":6,"reading":"わたし"},{"start":7,"end":9,"reading":"しょしき"},{"start":16,"end":19,"reading":"ほんやくしゃ"},{"start":28,"end":29,"reading":"き"}], background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.ZhouYining_Smile },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女は書いた。「ゴムパッキン確認済み。十元硬貨一枚と、持ち主不明の髪の毛一本を発見。勇気は発見に至らず。」そして真ん中の椅子に戻す。", ruby: [{"start":0,"end":2,"reading":"かのじょ"},{"start":3,"end":4,"reading":"か"},{"start":14,"end":17,"reading":"かくにんず"},{"start":19,"end":23,"reading":"じゅうげんこうか"},{"start":23,"end":25,"reading":"いちまい"},{"start":27,"end":28,"reading":"も"},{"start":29,"end":30,"reading":"ぬし"},{"start":30,"end":32,"reading":"ふめい"},{"start":33,"end":34,"reading":"かみ"},{"start":35,"end":36,"reading":"け"},{"start":36,"end":38,"reading":"いっぽん"},{"start":39,"end":41,"reading":"はっけん"},{"start":42,"end":44,"reading":"ゆうき"},{"start":45,"end":47,"reading":"はっけん"},{"start":48,"end":49,"reading":"いた"},{"start":56,"end":57,"reading":"ま"},{"start":58,"end":59,"reading":"なか"},{"start":60,"end":62,"reading":"いす"},{"start":63,"end":64,"reading":"もど"}], background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "読み終えた彼の肩が、一度だけ震えた。笑いをこらえているのだと、彼女には確信があった。", ruby: [{"start":0,"end":1,"reading":"よ"},{"start":2,"end":3,"reading":"お"},{"start":5,"end":6,"reading":"かれ"},{"start":7,"end":8,"reading":"かた"},{"start":10,"end":12,"reading":"いちど"},{"start":14,"end":15,"reading":"ふる"},{"start":18,"end":19,"reading":"わら"},{"start":31,"end":33,"reading":"かのじょ"},{"start":35,"end":37,"reading":"かくしん"}], background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "「十元あれば、二号がもう一回まわります。初診料としてお納めください。」", ruby: [{"start":1,"end":3,"reading":"じゅうげん"},{"start":7,"end":9,"reading":"にごう"},{"start":12,"end":14,"reading":"いっかい"},{"start":20,"end":23,"reading":"しょしんりょう"},{"start":27,"end":28,"reading":"おさ"}], background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "「当院では初診料はいただいておりません。ただ、ご家族が毎週四号を譲り、乾いていない服を持ち帰っておられる件については、当院でもずっと気にかけておりました。」", ruby: [{"start":1,"end":3,"reading":"とういん"},{"start":5,"end":8,"reading":"しょしんりょう"},{"start":24,"end":26,"reading":"かぞく"},{"start":27,"end":29,"reading":"まいしゅう"},{"start":29,"end":31,"reading":"よんごう"},{"start":32,"end":33,"reading":"ゆず"},{"start":35,"end":36,"reading":"かわ"},{"start":41,"end":42,"reading":"ふく"},{"start":43,"end":44,"reading":"も"},{"start":45,"end":46,"reading":"かえ"},{"start":52,"end":53,"reading":"けん"},{"start":59,"end":61,"reading":"とういん"},{"start":66,"end":67,"reading":"き"}], background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "今度は、彼の手が長いこと止まった。戻ってきたメモの字は小さくなっていた。場所を取るのを遠慮しているみたいに。", ruby: [{"start":0,"end":2,"reading":"こんど"},{"start":4,"end":5,"reading":"かれ"},{"start":6,"end":7,"reading":"て"},{"start":8,"end":9,"reading":"なが"},{"start":12,"end":13,"reading":"と"},{"start":17,"end":18,"reading":"もど"},{"start":25,"end":26,"reading":"じ"},{"start":27,"end":28,"reading":"ちい"},{"start":36,"end":38,"reading":"ばしょ"},{"start":39,"end":40,"reading":"と"},{"start":43,"end":45,"reading":"えんりょ"}], background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "「眠れないとき、ここに来ていました。そのうち、木曜日は少しよく眠れることに気づきました。」", ruby: [{"start":1,"end":2,"reading":"ねむ"},{"start":11,"end":12,"reading":"き"},{"start":23,"end":26,"reading":"もくようび"},{"start":27,"end":28,"reading":"すこ"},{"start":31,"end":32,"reading":"ねむ"},{"start":37,"end":38,"reading":"き"}], background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "その一行を、彼女は三回読んだ。外の雨は、いつのまにかやんでいた。", ruby: [{"start":2,"end":4,"reading":"いちぎょう"},{"start":6,"end":8,"reading":"かのじょ"},{"start":9,"end":11,"reading":"さんかい"},{"start":11,"end":12,"reading":"よ"},{"start":15,"end":16,"reading":"そと"},{"start":17,"end":18,"reading":"あめ"}], background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "ガラスにはまだ水滴が残っている。空は黒から薄れて、何度も洗ったような灰青色になっていた。向かいのコンビニの灯りが、朝の光の中で急にひどく疲れて見えた。", ruby: [{"start":7,"end":9,"reading":"すいてき"},{"start":10,"end":11,"reading":"のこ"},{"start":16,"end":17,"reading":"そら"},{"start":18,"end":19,"reading":"くろ"},{"start":21,"end":22,"reading":"うす"},{"start":25,"end":27,"reading":"なんど"},{"start":28,"end":29,"reading":"あら"},{"start":34,"end":37,"reading":"はいあおいろ"},{"start":44,"end":45,"reading":"む"},{"start":53,"end":54,"reading":"あか"},{"start":57,"end":58,"reading":"あさ"},{"start":59,"end":60,"reading":"ひかり"},{"start":61,"end":62,"reading":"なか"},{"start":63,"end":64,"reading":"きゅう"},{"start":68,"end":69,"reading":"つか"},{"start":71,"end":72,"reading":"み"}], background: Background.Branch_1a_B1a_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "メモの裏はもう埋まっていた。表に返し、「勇気」の二文字の横の余白に、最後の一行を書く。「周以寧。準夜勤。木曜日。」", ruby: [{"start":3,"end":4,"reading":"うら"},{"start":7,"end":8,"reading":"う"},{"start":14,"end":15,"reading":"おもて"},{"start":16,"end":17,"reading":"かえ"},{"start":20,"end":22,"reading":"ゆうき"},{"start":24,"end":27,"reading":"にもじ"},{"start":28,"end":29,"reading":"よこ"},{"start":30,"end":32,"reading":"よはく"},{"start":34,"end":36,"reading":"さいご"},{"start":37,"end":39,"reading":"いちぎょう"},{"start":40,"end":41,"reading":"か"},{"start":44,"end":47,"reading":"しゅういねい"},{"start":48,"end":51,"reading":"じゅんやきん"},{"start":52,"end":55,"reading":"もくようび"}], background: Background.Branch_1a_B1a_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "椅子には置かなかった。立ち上がって空いた椅子の前を通りすぎ、メモを彼の手に直接渡した。", ruby: [{"start":0,"end":2,"reading":"いす"},{"start":4,"end":5,"reading":"お"},{"start":11,"end":12,"reading":"た"},{"start":13,"end":14,"reading":"あ"},{"start":17,"end":18,"reading":"あ"},{"start":20,"end":22,"reading":"いす"},{"start":23,"end":24,"reading":"まえ"},{"start":25,"end":26,"reading":"とお"},{"start":33,"end":34,"reading":"かれ"},{"start":35,"end":36,"reading":"て"},{"start":37,"end":39,"reading":"ちょくせつ"},{"start":39,"end":40,"reading":"わた"}], background: Background.Branch_1a_B1a_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼が顔を上げる。近くで見ると、クマは思っていたよりずっと深かった。", ruby: [{"start":0,"end":1,"reading":"かれ"},{"start":2,"end":3,"reading":"かお"},{"start":4,"end":5,"reading":"あ"},{"start":8,"end":9,"reading":"ちか"},{"start":11,"end":12,"reading":"み"},{"start":18,"end":19,"reading":"おも"},{"start":28,"end":29,"reading":"ふか"}], background: Background.Branch_1a_B1a_Act4_S1 },
    { characterId: CharacterId.RedPen, character: "赤ペン", dialogue: "……江遠。", ruby: [{"start":2,"end":4,"reading":"こうえん"}], background: Background.Branch_1a_B1a_Act4_S1, portrait: Portrait.RedPen_Base },
    { characterId: CharacterId.RedPen, character: "赤ペン", dialogue: "江遠といいます。すみません、先に書くべきでした。僕は、口より字のほうが器用なので。", ruby: [{"start":0,"end":2,"reading":"こうえん"},{"start":14,"end":15,"reading":"さき"},{"start":16,"end":17,"reading":"か"},{"start":24,"end":25,"reading":"ぼく"},{"start":27,"end":28,"reading":"くち"},{"start":30,"end":31,"reading":"じ"},{"start":35,"end":37,"reading":"きよう"}], background: Background.Branch_1a_B1a_Act4_S1, portrait: Portrait.RedPen_Smile },
    { characterId: CharacterId.ZhouYining, character: "以寧", dialogue: "知ってます。壁の貼り紙を直したのも、江遠さんですよね。", ruby: [{"start":0,"end":1,"reading":"し"},{"start":6,"end":7,"reading":"かべ"},{"start":8,"end":9,"reading":"は"},{"start":10,"end":11,"reading":"がみ"},{"start":12,"end":13,"reading":"なお"},{"start":18,"end":20,"reading":"こうえん"}], background: Background.Branch_1a_B1a_Act4_S1, portrait: Portrait.ZhouYining_Base },
    { characterId: CharacterId.RedPen, character: "赤ペン", dialogue: "動物を入れるな、とは書いてあったので。人のことも書いておくべきかと。", ruby: [{"start":0,"end":2,"reading":"どうぶつ"},{"start":3,"end":4,"reading":"い"},{"start":10,"end":11,"reading":"か"},{"start":19,"end":20,"reading":"ひと"},{"start":24,"end":25,"reading":"か"}], background: Background.Branch_1a_B1a_Act4_S1, portrait: Portrait.RedPen_Base },
    { characterId: CharacterId.ZhouYining, character: "以寧", dialogue: "用意周到ですね。チャック袋と同じくらい。", ruby: [{"start":0,"end":4,"reading":"よういしゅうとう"},{"start":12,"end":13,"reading":"ぶくろ"},{"start":14,"end":15,"reading":"おな"}], background: Background.Branch_1a_B1a_Act4_S1, portrait: Portrait.ZhouYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼の耳がまた赤くなった。今回は呼吸を数えないでおこう、と彼女は決めた。", ruby: [{"start":0,"end":1,"reading":"かれ"},{"start":2,"end":3,"reading":"みみ"},{"start":6,"end":7,"reading":"あか"},{"start":12,"end":14,"reading":"こんかい"},{"start":15,"end":17,"reading":"こきゅう"},{"start":18,"end":19,"reading":"かぞ"},{"start":28,"end":30,"reading":"かのじょ"},{"start":31,"end":32,"reading":"き"}], background: Background.Branch_1a_B1a_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼が豆乳を差し出した。とっくに熱くはなく、ぬるくなっていた。四号で半分だけ乾かした服みたいに。", ruby: [{"start":0,"end":1,"reading":"かれ"},{"start":2,"end":4,"reading":"とうにゅう"},{"start":5,"end":6,"reading":"さ"},{"start":7,"end":8,"reading":"だ"},{"start":15,"end":16,"reading":"あつ"},{"start":30,"end":32,"reading":"よんごう"},{"start":33,"end":35,"reading":"はんぶん"},{"start":37,"end":38,"reading":"かわ"},{"start":41,"end":42,"reading":"ふく"}], background: Background.Branch_1a_B1a_Act4_S1 },
    { characterId: CharacterId.RedPen, character: "赤ペン", dialogue: "これ、本当は周さんに買ったんです。向かいで立っている時間が、長すぎただけで。", ruby: [{"start":3,"end":5,"reading":"ほんとう"},{"start":6,"end":7,"reading":"しゅう"},{"start":10,"end":11,"reading":"か"},{"start":17,"end":18,"reading":"む"},{"start":21,"end":22,"reading":"た"},{"start":26,"end":28,"reading":"じかん"},{"start":30,"end":31,"reading":"なが"}], background: Background.Branch_1a_B1a_Act4_S1, portrait: Portrait.RedPen_Base },
    { characterId: CharacterId.ZhouYining, character: "以寧", dialogue: "ぬるいくらいがちょうどいいです。仕事明けは、熱いのは飲めないので。", ruby: [{"start":16,"end":19,"reading":"しごとあ"},{"start":22,"end":23,"reading":"あつ"},{"start":26,"end":27,"reading":"の"}], background: Background.Branch_1a_B1a_Act4_S1, portrait: Portrait.ZhouYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "二人は一緒に店を出た。アーケードの下にはスクーターが二台。彼女のと、彼のと、そのあいだに知らない誰かのが一台。", ruby: [{"start":0,"end":2,"reading":"ふたり"},{"start":3,"end":5,"reading":"いっしょ"},{"start":6,"end":7,"reading":"みせ"},{"start":8,"end":9,"reading":"で"},{"start":17,"end":18,"reading":"した"},{"start":26,"end":28,"reading":"にだい"},{"start":29,"end":31,"reading":"かのじょ"},{"start":34,"end":35,"reading":"かれ"},{"start":44,"end":45,"reading":"し"},{"start":48,"end":49,"reading":"だれ"},{"start":52,"end":54,"reading":"いちだい"}], background: Background.Branch_1a_B1a_Act4_S2 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "この半年、二人のあいだにはずっと、知らない誰かのスクーターが一台はさまっていたのだ。", ruby: [{"start":2,"end":4,"reading":"はんとし"},{"start":5,"end":7,"reading":"ふたり"},{"start":17,"end":18,"reading":"し"},{"start":21,"end":22,"reading":"だれ"},{"start":30,"end":32,"reading":"いちだい"}], background: Background.Branch_1a_B1a_Act4_S2 },
    { characterId: CharacterId.RedPen, character: "赤ペン", dialogue: "あの……もう片方の靴下、来週の木曜に持ってきます。ちゃんと一足にします。", ruby: [{"start":6,"end":8,"reading":"かたほう"},{"start":9,"end":11,"reading":"くつした"},{"start":12,"end":14,"reading":"らいしゅう"},{"start":15,"end":17,"reading":"もくよう"},{"start":18,"end":19,"reading":"も"},{"start":29,"end":31,"reading":"いっそく"}], background: Background.Branch_1a_B1a_Act4_S2, portrait: Portrait.RedPen_Base },
    { characterId: CharacterId.ZhouYining, character: "以寧", dialogue: "洗濯機に食べられたって、言ってませんでした？", ruby: [{"start":0,"end":3,"reading":"せんたくき"},{"start":4,"end":5,"reading":"た"},{"start":12,"end":13,"reading":"い"}], background: Background.Branch_1a_B1a_Act4_S2, portrait: Portrait.ZhouYining_Base },
    { characterId: CharacterId.RedPen, character: "赤ペン", dialogue: "はい。なんとかして吐き出させます。", ruby: [{"start":9,"end":10,"reading":"は"},{"start":11,"end":12,"reading":"だ"}], background: Background.Branch_1a_B1a_Act4_S2, portrait: Portrait.RedPen_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女は声を出して笑った。半年で初めて、彼の前で声を出して笑った。", ruby: [{"start":0,"end":2,"reading":"かのじょ"},{"start":3,"end":4,"reading":"こえ"},{"start":5,"end":6,"reading":"だ"},{"start":8,"end":9,"reading":"わら"},{"start":12,"end":14,"reading":"はんとし"},{"start":15,"end":16,"reading":"はじ"},{"start":19,"end":20,"reading":"かれ"},{"start":21,"end":22,"reading":"まえ"},{"start":23,"end":24,"reading":"こえ"},{"start":25,"end":26,"reading":"だ"},{"start":28,"end":29,"reading":"わら"}], background: Background.Branch_1a_B1a_Act4_S2 },
    { characterId: CharacterId.ZhouYining, character: "以寧", dialogue: "うん。じゃあ、また木曜日に。", ruby: [{"start":9,"end":12,"reading":"もくようび"}], background: Background.Branch_1a_B1a_Act4_S2, portrait: Portrait.ZhouYining_Smile },
    { characterId: CharacterId.RedPen, character: "赤ペン", dialogue: "また木曜日に。", ruby: [{"start":2,"end":5,"reading":"もくようび"}], background: Background.Branch_1a_B1a_Act4_S2, portrait: Portrait.RedPen_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "アーケードからスクーターを出したとき、空はまた少し明るくなっていた。ミラーの中で、彼はまだコインランドリーの入口に立っていた。字でびっしり埋まったメモを、とても大事な原稿のように握りしめて。", ruby: [{"start":13,"end":14,"reading":"だ"},{"start":19,"end":20,"reading":"そら"},{"start":23,"end":24,"reading":"すこ"},{"start":25,"end":26,"reading":"あか"},{"start":38,"end":39,"reading":"なか"},{"start":41,"end":42,"reading":"かれ"},{"start":54,"end":56,"reading":"いりぐち"},{"start":57,"end":58,"reading":"た"},{"start":63,"end":64,"reading":"じ"},{"start":69,"end":70,"reading":"う"},{"start":80,"end":82,"reading":"だいじ"},{"start":83,"end":85,"reading":"げんこう"},{"start":89,"end":90,"reading":"にぎ"}], background: Background.Branch_1a_B1a_Act4_S2 },
    { characterId: CharacterId.ZhouYining, character: "以寧", dialogue: "（心の声）来週の木曜日は、四号を先に譲ってあげよう。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":5,"end":7,"reading":"らいしゅう"},{"start":8,"end":11,"reading":"もくようび"},{"start":13,"end":15,"reading":"よんごう"},{"start":16,"end":17,"reading":"さき"},{"start":18,"end":19,"reading":"ゆず"}], background: Background.Branch_1a_B1a_Act4_S2, portrait: Portrait.ZhouYining_Base },
];
